package javax.microedition.lcdui;public class List extends Screen implements Choice {public static final Command SELECT_COMMAND=new Command("Select",Command.OK,0);private Command select=SELECT_COMMAND;private java.util.Vector strings=new java.util.Vector(),images=new java.util.Vector();private java.util.Vector flags=new java.util.Vector(),fonts=new java.util.Vector();private int selected,policy,type;private void check(int i){if(i<0||i>=size())throw new IndexOutOfBoundsException();}public List(String title,int type){if(type!=EXCLUSIVE&&type!=MULTIPLE&&type!=IMPLICIT)throw new IllegalArgumentException();setTitle(title);this.type=type;}public List(String title,int type,String[]s,Image[]im){this(title,type);if(s==null)throw new NullPointerException();if(im!=null&&im.length!=s.length)throw new IllegalArgumentException();for(int i=0;i<s.length;i++)append(s[i],im==null?null:im[i]);}public int size(){return strings.size();}public String getString(int i){return (String)strings.elementAt(i);}public Image getImage(int i){return (Image)images.elementAt(i);}public int append(String s,Image im){if(s==null)throw new NullPointerException();strings.addElement(s);images.addElement(im);flags.addElement(Boolean.FALSE);fonts.addElement(null);repaint();return size()-1;}public void insert(int i,String s,Image im){if(s==null)throw new NullPointerException();if(i<0||i>size())throw new IndexOutOfBoundsException();if(size()>0&&i<=selected)selected++;strings.insertElementAt(s,i);images.insertElementAt(im,i);flags.insertElementAt(Boolean.FALSE,i);fonts.insertElementAt(null,i);repaint();}public void delete(int i){check(i);strings.removeElementAt(i);images.removeElementAt(i);flags.removeElementAt(i);fonts.removeElementAt(i);if(i<selected)selected--;selected=Math.max(0,Math.min(selected,size()-1));repaint();}public void deleteAll(){strings.removeAllElements();images.removeAllElements();flags.removeAllElements();fonts.removeAllElements();selected=0;repaint();}public void set(int i,String s,Image im){check(i);if(s==null)throw new NullPointerException();strings.setElementAt(s,i);images.setElementAt(im,i);repaint();}public boolean isSelected(int i){check(i);return type==MULTIPLE?((Boolean)flags.elementAt(i)).booleanValue():i==selected;}public int getSelectedIndex(){return type==MULTIPLE||size()==0?-1:selected;}public int getSelectedFlags(boolean[]f){if(f==null)throw new NullPointerException();if(f.length<size())throw new IllegalArgumentException();int n=0;for(int i=0;i<f.length;i++){f[i]=i<size()&&isSelected(i);if(f[i])n++;}return n;}public void setSelectedIndex(int i,boolean b){if(i<0||i>=size())throw new IndexOutOfBoundsException();if(type==MULTIPLE)flags.setElementAt(Boolean.valueOf(b),i);else if(b)selected=i;repaint();}public void setSelectedFlags(boolean[]f){if(f==null)throw new NullPointerException();if(f.length<size())throw new IllegalArgumentException();if(type==MULTIPLE){for(int i=0;i<size();i++)flags.setElementAt(Boolean.valueOf(f[i]),i);}else{selected=0;for(int i=0;i<size();i++)if(f[i]){selected=i;break;}}repaint();}public void setFitPolicy(int p){if(p!=TEXT_WRAP_DEFAULT&&p!=TEXT_WRAP_ON&&p!=TEXT_WRAP_OFF)throw new IllegalArgumentException();policy=p;}public int getFitPolicy(){return policy;}public void setFont(int i,Font f){check(i);fonts.setElementAt(f,i);}public Font getFont(int i){check(i);Font f=(Font)fonts.elementAt(i);return f==null?Font.getDefaultFont():f;}public void setSelectCommand(Command c){select=c;}protected void keyPressed(int k){if(k==-6||k==-7){super.keyPressed(k);return;}int a=getGameAction(k);if(size()>0){if(a==UP)selected=(selected+size()-1)%size();if(a==DOWN)selected=(selected+1)%size();}if(a==FIRE&&size()>0&&type==MULTIPLE)setSelectedIndex(selected,!isSelected(selected));if(a==FIRE&&type==IMPLICIT&&listener!=null&&select!=null)listener.commandAction(select,this);repaint();}protected void paint(Graphics g){g.setColor(0x122638);g.fillRect(0,0,getWidth(),getHeight());g.setColor(0xffffff);g.drawString(getTitle()==null?"":getTitle(),8,8,20);int start=Math.max(0,selected-(getHeight()/18-3));for(int i=start;i<size()&&i<start+getHeight()/18-2;i++){int y=32+(i-start)*18;if(i==selected){g.setColor(0x326681);g.fillRect(4,y-2,getWidth()-8,17);}g.setColor(0xffffff);g.drawString(getString(i),8,y,20);}}}
